import json, sys, glob

def dump(f, show_content=True):
    d = json.load(open(f))
    ri = (d['rollout'].get('metadata') or {}).get('tau2_reward_info') or {}
    print(f"\n===== {f}  reward={ri.get('reward')} db_match={(ri.get('db_check') or {}).get('db_match')} =====")
    out = d['rollout']['output']
    for m in out:
        role = m.get('role')
        if role == 'assistant':
            tcs = m.get('tool_calls')
            content = (m.get('content') or '').strip()
            if content and show_content:
                print(f"[ASST] {content[:400]}")
            if tcs:
                for tc in tcs:
                    print(f"  >>> CALL {tc.get('name')} {json.dumps(tc.get('arguments'))[:600]}")
        elif role == 'tool':
            content = (m.get('content') or '')
            if isinstance(content, list):
                content = json.dumps(content)
            err = m.get('error')
            tag = 'TOOL-ERR' if err else 'TOOL'
            print(f"  <<< {tag} {str(content)[:400]}")
        elif role == 'user':
            content = (m.get('content') or '').strip()
            if content and show_content:
                print(f"[USER] {content[:300]}")

def gold(f):
    d = json.load(open(f))
    ri = (d['rollout'].get('metadata') or {}).get('tau2_reward_info') or {}
    print(f"\n== GOLD action_checks for {f} (reward={ri.get('reward')}) ==")
    for ac in ri.get('action_checks') or []:
        a = ac['action']
        print(f"  match={ac['action_match']} {a['name']} {json.dumps(a['arguments'])[:400]}")

if __name__ == '__main__':
    mode = sys.argv[1]
    if mode == 'gold':
        gold(sys.argv[2])
    else:
        dump(sys.argv[1], show_content=('nocontent' not in sys.argv))
